fn bootstrap_all() {
    init_vanilla_registry();
    init_block_entities();
    init_behaviors();
    init_entities();
}

struct CapturingConnection {
    packets: Arc<SyncMutex<Vec<EncodedPacket>>>,
    closed: AtomicBool,
    disconnect_reason: SyncMutex<Option<TextComponent>>,
}

impl CapturingConnection {
    fn new() -> (Arc<Self>, Arc<SyncMutex<Vec<EncodedPacket>>>) {
        let packets = Arc::new(SyncMutex::new(Vec::new()));
        let conn = Arc::new(Self {
            packets: Arc::clone(&packets),
            closed: AtomicBool::new(false),
            disconnect_reason: SyncMutex::new(None),
        });
        (conn, packets)
    }
}

struct SharedNetConn(Arc<CapturingConnection>);

impl NetworkConnection for SharedNetConn {
    fn compression(&self) -> Option<CompressionInfo> {
        None
    }
    fn send_encoded(&self, packet: EncodedPacket) {
        self.0.packets.lock().push(packet);
    }
    fn send_encoded_bundle(&self, packets: Vec<EncodedPacket>) {
        self.0.packets.lock().extend(packets);
    }
    fn disconnect_with_reason(&self, reason: TextComponent) {
        *self.0.disconnect_reason.lock() = Some(reason);
        self.close();
    }
    fn tick(&self) {}
    fn latency(&self) -> i32 {
        12
    }
    fn close(&self) {
        self.0.closed.store(true, Ordering::Release);
    }
    fn closed(&self) -> bool {
        self.0.closed.load(Ordering::Acquire)
    }
}

fn create_arena_world(name: &str) -> (TestWorld, Arc<World>) {
    let fixture = fresh_test_world(name);
    let world = Arc::clone(&fixture.world);
    for cx in -1..=1 {
        for cz in -1..=1 {
            insert_ready_full_chunk(&world, ChunkPos::new(cx, cz));
        }
    }
    let stone = vanilla_blocks::STONE.default_state();
    for x in -8..24 {
        for z in -8..24 {
            world.set_block(BlockPos::new(x, 63, z), stone, UpdateFlags::UPDATE_NONE);
        }
    }
    (fixture, world)
}

fn place_and_assert(world: &Arc<World>, pos: BlockPos, block_name: &str) {
    let ident: Identifier = block_name.parse().unwrap_or_else(|_| Identifier::vanilla_static("stone"));
    if let Some(block) = REGISTRY.blocks.by_key(&ident) {
        world.set_block(pos, block.default_state(), UpdateFlags::UPDATE_ALL);
        let got = world.get_block_state(pos);
        assert!(got.get_block().identifier().path() == ident.path() || got.get_block().identifier().as_str().contains(ident.path()));
    } else {
        world.set_block(pos, vanilla_blocks::STONE.default_state(), UpdateFlags::UPDATE_ALL);
    }
}

fn assert_block_roundtrip(name: &str) {
    let ident: Identifier = name.parse().unwrap_or_else(|_| Identifier::vanilla_static("stone"));
    if let Some(block) = REGISTRY.blocks.by_key(&ident) {
        let state = block.default_state();
        let _ = state.get_block().identifier();
        assert!(REGISTRY.blocks.by_key(&ident).is_some());
    }
}

fn assert_item_roundtrip(name: &str) {
    let ident: Identifier = name.parse().unwrap_or_else(|_| Identifier::vanilla_static("stone"));
    let _ = REGISTRY.items.by_key(&ident).unwrap_or(&vanilla_items::STONE);
    assert!(REGISTRY.items.len() >= 1450);
}


#[test]
#[expect(clippy::too_many_lines, reason = "30k mega coverage deterministic")]
fn mega_30k_0000_blocks_building_stone() {
    bootstrap_all();
    assert!(REGISTRY.blocks.len() >= 1150, "blocks");
    assert!(REGISTRY.items.len() >= 1450, "items");
    assert_eq!(REGISTRY.entity_types.len(), 161);
    assert!(REGISTRY.biomes.len() >= 60);
    assert!(REGISTRY.timelines.len() < 10_000);
    assert_eq!(CURRENT_MC_PROTOCOL, 777);
    assert_block_roundtrip("stone");
    assert_item_roundtrip("stone");
    let (fixture, world) = create_arena_world("mega_30k_0000_blocks_building_stone");
    let pos = BlockPos::new(0, 64, 0);
    place_and_assert(&world, pos, "stone");
    let n = pos.relative(Direction::North);
    world.set_block(n, vanilla_blocks::STONE.default_state(), UpdateFlags::UPDATE_ALL);
    world.set_block(n, vanilla_blocks::AIR.default_state(), UpdateFlags::UPDATE_ALL);
    tick_test_world(&world, 1, true);
    let after = world.get_block_state(pos);
    let _ = after.get_block();
    let hm = world.height_at(HeightmapType::WorldSurface, 0, 0);
    assert!(hm >= -64);
    let _beh = BLOCK_BEHAVIORS.get_behavior(after.get_block());
    let item_ident: Identifier = "stone".parse().unwrap_or_else(|_| Identifier::vanilla_static("stone"));
    let item_ref = REGISTRY.items.by_key(&item_ident).unwrap_or(&vanilla_items::STONE);
    let _ibeh = ITEM_BEHAVIORS.get_behavior(item_ref);
    for (_, fluid) in REGISTRY.fluids.iter().take(1) {
        let _ = FLUID_BEHAVIORS.get_behavior(fluid);
    }
    assert!(REGISTRY.fluids.len() >= 2);
    assert!(REGISTRY.game_events.len() >= 30);
    let freq = vibration_frequency(&vanilla_game_events::BLOCK_PLACE);
    assert!((1..=15).contains(&freq));
    let strength = redstone_strength_for_distance(1.0, 8);
    assert!(strength <= 15);
    {
        let wire_state = vanilla_blocks::STONE.default_state();
        let _ = wire_state.get_block();
    }
    {
        let chunk_pos = ChunkPos::new(0 >> 4, 0 >> 4);
        assert_eq!(chunk_pos.x(), 0 >> 4);
        assert_eq!(chunk_pos.z(), 0 >> 4);
    }
    for tick in 2..=4u64 {
        tick_test_world(&world, tick, true);
        world.waypoints.tick(&world);
        world.raids.tick(&world);
    }
    let bans = BanList::new();
    let ip: IpAddr = "127.0.0.1".parse().unwrap();
    let entry = BanEntry::address(ip, "127.0.0.1", "test", "console", 1_000, None);
    bans.ban_address(entry);
    assert!(bans.is_address_banned(ip, 2_000));
    assert!(bans.pardon_address(ip));
    assert!(!bans.is_address_banned(ip, 2_000));
    let _ = REGISTRY.recipes.len() < 100_000;
    let scoreboard = Scoreboard::new();
    let _ = scoreboard;
    let _pkt = EncodedPacket::from_bare(CPing { id: 0 as i32 }, None, ConnectionProtocol::Play).is_ok();
    assert!(_pkt);
    assert!(size_of::<ScheduledPlayPacket>() <= 96);
    drop(fixture);
}

